102	    /**
103	     * 离线提交：基于 baseVersion 的三方合并。合并结果与当前完全相同则不加版本，否则版本加一。
104	     */
105	    @Transactional
106	    public WriteOutcome merge(String observationId, MergeObservationRequest request) {
107	        String fingerprint = fingerprint("MERGE", observationId, String.valueOf(request.baseVersion()),
108	                request.location(), request.reading(), request.note());
109	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
110	        if (replayed != null) {
111	            return replayed;
112	        }
113	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "MERGE");
114	        if (concurrent != null) {
115	            return concurrent;
116	        }
117	
118	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
119	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
120	        if (current.deleted()) {
121	            throw ApiException.gone("observation already deleted: " + observationId);
122	        }
123	        ObservationSnapshot base = observationRepository.findVersion(observationId, request.baseVersion())
124	                .orElseThrow(() -> ApiException.notFound(
125	                        "base version not found: " + observationId + "@" + request.baseVersion()));
126	        // 代次隔离：仅接受本代次的基线；墓碑恢复后旧代次的离线修改不得直接灌入恢复后的记录。
127	        if (base.generation() != current.generation()) {
128	            throw ApiException.conflict(
129	                    "baseVersion belongs to a stale merge generation; re-read the current baseline: "
130	                            + observationId + "@" + request.baseVersion(),
131	                    current.version());
132	        }
133	
134	        List<String> conflictFields = new ArrayList<>();
135	        String mergedLocation = mergeField("location", base.location(), current.location(),
136	                request.location(), conflictFields);
137	        String mergedReading = mergeReadingField(base.reading(), current.reading(),
138	                request.reading(), conflictFields);
139	        String mergedNote = mergeField("note", base.note(), current.note(), request.note(), conflictFields);
140	        if (!conflictFields.isEmpty()) {
141	            throw ApiException.mergeConflict(conflictFields, current.version());
142	        }
143	
144	        ObservationSnapshot merged = new ObservationSnapshot(observationId, current.version(),
145	                current.generation(), mergedLocation, mergedReading, mergedNote, false);
146	        if (sameContent(merged, current)) {
147	            // 合并结果与当前完全相同：返回当前版本，不加版本
148	            return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(current));
149	        }
150	        ObservationSnapshot next = new ObservationSnapshot(observationId, current.version() + 1,
151	                current.generation(), mergedLocation, mergedReading, mergedNote, false);
152	        observationRepository.updateCurrent(next);
153	        observationRepository.insertVersion(next);
154	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(next));
155	    }
