157	    /**
158	     * 删除观测记录：expectedVersion 匹配当前版本时生成新版本墓碑；已删除记录返回 410。
159	     */
160	    @Transactional
161	    public WriteOutcome delete(String observationId, DeleteObservationRequest request) {
162	        String fingerprint = fingerprint("DELETE", observationId, String.valueOf(request.expectedVersion()));
163	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
164	        if (replayed != null) {
165	            return replayed;
166	        }
167	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "DELETE");
168	        if (concurrent != null) {
169	            return concurrent;
170	        }
171	
172	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
173	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
174	        if (current.deleted()) {
175	            throw ApiException.gone("observation already deleted: " + observationId);
176	        }
177	        if (request.expectedVersion() != current.version()) {
178	            throw ApiException.conflict("expectedVersion mismatch", current.version());
179	        }
180	        ObservationSnapshot tombstone = new ObservationSnapshot(observationId, current.version() + 1,
181	                current.generation(), null, null, null, true);
182	        observationRepository.markDeleted(observationId, tombstone.version());
183	        observationRepository.insertVersion(tombstone);
184	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(tombstone));
185	    }
186	
187	    /**
188	     * 墓碑显式恢复：仅当当前为墓碑且 expectedVersion 匹配当前墓碑版本时允许恢复。
189	     * 来源必须是本记录已存在的非墓碑历史版本（可跨代次）；恢复复制其地点、读数与备注，
190	     * 生成“墓碑版本 + 1”的新快照，不回退版本、不改写任何历史快照/冲突解决记录/墓碑，
191	     * 合并代次加一。与其他写操作共用同一套 requestId 幂等规则。
192	     */
193	    @Transactional
194	    public WriteOutcome restore(String observationId, RestoreObservationRequest request) {
195	        String fingerprint = fingerprint("RESTORE", observationId,
196	                String.valueOf(request.expectedVersion()), String.valueOf(request.sourceVersion()),
197	                request.reason());
198	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
199	        if (replayed != null) {
200	            return replayed;
201	        }
202	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "RESTORE");
203	        if (concurrent != null) {
204	            return concurrent;
205	        }
206	
207	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
208	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
209	        // 当前非墓碑：不允许恢复，返回 409 并给出当前版本。
210	        if (!current.deleted()) {
211	            throw ApiException.conflict("observation is not a tombstone: " + observationId,
212	                    current.version());
213	        }
214	        if (request.expectedVersion() != current.version()) {
215	            throw ApiException.conflict("expectedVersion mismatch", current.version());
216	        }
217	        ObservationSnapshot source = observationRepository.findVersion(observationId, request.sourceVersion())
218	                .orElseThrow(() -> ApiException.notFound(
219	                        "source version not found: " + observationId + "@" + request.sourceVersion()));
220	        // 来源为墓碑：语义不合法，返回 422。
221	        if (source.deleted()) {
222	            throw ApiException.unprocessable(
223	                    "source version is a tombstone: " + observationId + "@" + request.sourceVersion(),
224	                    current.version());
225	        }
226	
227	        int newGeneration = current.generation() + 1;
228	        ObservationSnapshot restored = new ObservationSnapshot(observationId, current.version() + 1,
229	                newGeneration, source.location(), source.reading(), source.note(), false);
230	        observationRepository.restoreCurrent(restored);
231	        observationRepository.insertVersion(restored);
232	
233	        RecoveryRecord record = new RecoveryRecord(
234	                observationId, restored.version(), current.version(), source.version(),
235	                current.generation(), newGeneration, request.reason(), request.requestId(),
236	                Instant.now(clock));
237	        recoveryRepository.insert(record);
238	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(restored));
239	    }
240	
241	    /**
242	     * 按 observationId 查询墓碑恢复历史，按恢复时刻先后排序；观测记录不存在返回 404。只读不写。
243	     */
244	    @Transactional(readOnly = true)
245	    public List<RecoveryRecord> listRecoveries(String observationId) {
246	        observationRepository.findCurrent(observationId)
247	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
248	        return recoveryRepository.findByObservationId(observationId);
249	    }
250	
251	    /**
252	     * 查询当前内容；墓碑只返回删除状态和版本。
253	     */
254	    @Transactional(readOnly = true)
255	    public ObservationResponse getCurrent(String observationId) {
256	        ObservationSnapshot current = observationRepository.findCurrent(observationId)
257	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
258	        return ObservationResponse.of(current);
259	    }
260	
261	    /**
262	     * 显式冲突解决：事务内重读基线与最新当前版本并按原三方规则重算冲突，不信任客户端上次看到的冲突列表。
263	     * 选择恰好覆盖本次仍冲突字段时生成新版本（内容无变化则不加版本）并原子写入不可变解决记录。
264	     */
265	    @Transactional
266	    public ResolveOutcome resolveConflict(String observationId, ResolveConflictRequest request) {
267	        Map<String, FieldSelection> selections = parseSelections(request.selections());
268	        String normalizedSelections = writeSelectionsJson(selections);
269	        String fingerprint = fingerprint("RESOLVE", observationId, request.resolutionId(),
270	                String.valueOf(request.baseVersion()), String.valueOf(request.expectedCurrentVersion()),
271	                request.location(), request.reading(), request.note(), normalizedSelections, request.operator());
272	        ResolveOutcome replayed = checkResolveReplay(request.requestId(), fingerprint);
273	        if (replayed != null) {
274	            return replayed;
275	        }
276	        ResolveOutcome concurrent = insertResolvePlaceholder(request.requestId(), fingerprint);
277	        if (concurrent != null) {
278	            return concurrent;
279	        }
280	
281	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
282	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
283	
284	        // resolutionId 重放判定先于墓碑与版本校验：同参重放始终返回原结果（即使记录之后已被删除）；
285	        // 改参或跨记录复用一律 409。
286	        ResolutionRecord existing = resolutionRepository.findByResolutionId(request.resolutionId()).orElse(null);
287	        if (existing != null) {
288	            if (!sameResolutionParams(existing, observationId, request, normalizedSelections)) {
289	                throw ApiException.conflict(
290	                        "resolutionId reused with different parameters: " + request.resolutionId(),
291	                        current.version());
292	            }
293	            return completeResolve(request.requestId(), HttpStatus.OK, resolutionResponseOf(existing));
294	        }
295	
296	        if (current.deleted()) {
297	            throw ApiException.gone("observation already deleted: " + observationId);
