        body.put("resolutionId", "res-stale");
        body.put("baseVersion", 1);
        body.put("expectedCurrentVersion", 4);
        body.put("location", "站点X");
        body.put("reading", "9.0");
        body.put("note", "离线备注");
        body.put("selections", Map.of());
        body.put("operator", "op-1");
        resolve("obs-12", body)
