    }

    @Test
    void replayRestoreAfterAnotherDeleteReturnsOriginalResultWithoutRestoringAgain() throws Exception {
        seedDeletedAtV3("obs-17");
        restore("req-r", "obs-17", 3, 1, "恢复").andExpect(status().isOk());
        // 恢复后再次删除
