    @Test
    void oldSuccessfulMergeReplayKeepsOriginalSemanticsAcrossGeneration() throws Exception {
        seedDeletedAtV3("obs-18");
        // 旧 merge 已成功（v2）；恢复代次推进后，同键同参重放仍返回原结果，代次限制只作用于新操作
